-- ============================================================
-- AG STORE — ĐỒNG BỘ 167 SẢN PHẨM + GIÁ & SỐ LƯỢNG CHUẨN EXCEL (20261123)
-- ============================================================

alter table public.zaloshop_products add column if not exists is_visible boolean not null default true;
alter table public.zaloshop_products add column if not exists is_featured boolean not null default false;
alter table public.zaloshop_products add column if not exists gia_le integer not null default 0;
alter table public.zaloshop_products add column if not exists gia_si integer not null default 0;
alter table public.zaloshop_products add column if not exists gia_pdq integer not null default 0;
alter table public.zaloshop_products add column if not exists don_vi text not null default 'Hộp';
alter table public.zaloshop_products add column if not exists quy_cach text not null default '';

delete from public.zaloshop_products where id not like 'excel_%' or image_url = '' or image_url = '/ag-logo.jpg';

on conflict (id) do update set
  warehouse_name = excluded.warehouse_name, item_id = excluded.item_id, code = excluded.code,
  category = excluded.category, name = excluded.name, so_luong = excluded.so_luong,
  is_out_of_stock = excluded.is_out_of_stock, is_visible = true, is_featured = excluded.is_featured,
  gia_le = excluded.gia_le, gia_si = excluded.gia_si, gia_pdq = excluded.gia_pdq,
  don_vi = excluded.don_vi, quy_cach = excluded.quy_cach, ghi_chu = excluded.ghi_chu,
  rel_path = excluded.rel_path, image_url = excluded.image_url, updated_at = now();
